import{_ as s,o as t,c as a,a3 as n}from"./chunks/framework.DAK02U1-.js";const k=JSON.parse('{"title":"The xclang Command","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"The xclang Command | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/xclang-command"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/xclang-command"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/xclang-command"}]]},"headers":[],"relativePath":"xclang/reference/xclang-command.md","filePath":"en/xclang/reference/xclang-command.md","lastUpdated":1791301679000}'),i={name:"xclang/reference/xclang-command.md"};function o(d,e,c,r,l,h){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="the-xclang-command" tabindex="-1">The xclang Command <a class="header-anchor" href="#the-xclang-command" aria-label="Permalink to &quot;The xclang Command&quot;">​</a></h1><p><code>xclang</code> fetches what the toolchain does not carry: the vendor SDKs that cannot be redistributed, and targets beyond the six every toolchain has. Every toolchain archive carries it, as <code>bin/xclang</code> (<code>xclang.exe</code> on Windows), since 23.1.2.7. Why SDKs are fetched and not shipped is in <a href="./../design/vendor-sdks">vendor SDKs</a>. No release publishes target archives yet, so <code>xclang target add</code> has nothing to add; target archives are <a href="./../design/roadmap#target-archives">planned</a>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xclang sdk list [macos|windows]</span></span>
<span class="line"><span>xclang sdk fetch macos --accept-license [--preset P] [--version V]</span></span>
<span class="line"><span>xclang sdk fetch windows --accept-license [--preset P] [--msvc-version V] [--sdk-version V] [--arch x86_64,aarch64,x86]</span></span>
<span class="line"><span>xclang sdk path macos|windows [the options of fetch]</span></span>
<span class="line"><span>xclang sdk use &lt;name&gt;</span></span>
<span class="line"><span>xclang sdk remove &lt;name&gt;</span></span>
<span class="line"><span>xclang target list</span></span>
<span class="line"><span>xclang target add &lt;target&gt;...</span></span>
<span class="line"><span>xclang target remove &lt;target&gt;...</span></span>
<span class="line"><span>xclang --version</span></span></code></pre></div><h2 id="vendor-sdks" tabindex="-1">Vendor SDKs <a class="header-anchor" href="#vendor-sdks" aria-label="Permalink to &quot;Vendor SDKs&quot;">​</a></h2><p><code>xclang sdk fetch</code> downloads an SDK from its vendor. It checks each download against the size and sha256 its version table pins, with three tries, since a download now and then comes short or damaged. Then it unpacks the SDK into a directory of its own:</p><table tabindex="0"><thead><tr><th>SDK</th><th>directory</th><th>use</th></tr></thead><tbody><tr><td>macOS</td><td><code>$XCLANG/sdk/macos-&lt;version&gt;</code></td><td><code>clang++ --target=arm64-apple-macos</code> on Linux and Windows hosts (<a href="./../design/macos#the-sdk-on-linux-and-windows-hosts">macOS</a>); on macOS hosts, and for an SDK outside the toolchain, <code>-isysroot &lt;dir&gt;</code></td></tr><tr><td>MSVC and the Windows SDK</td><td><code>$XCLANG/sdk/windows-msvc&lt;version&gt;-sdk&lt;version&gt;</code></td><td><code>clang++ --target=x86_64-pc-windows-msvc</code>, <code>clang-cl</code>: the <a href="./../integrations/clang#msvc-targets">MSVC targets</a></td></tr></tbody></table><table tabindex="0"><thead><tr><th>command or option</th><th></th></tr></thead><tbody><tr><td><code>--accept-license</code></td><td>without it, fetch prints the vendor&#39;s license terms and stops</td></tr><tr><td><code>sdk path</code></td><td>prints the directory that fetch, with the same options, fetches to: <code>-isysroot &quot;$(xclang sdk path macos)&quot;</code></td></tr><tr><td><code>sdk list</code></td><td>the fetched SDKs, and those in use; <code>.xclang-sdk.json</code>, written last, records what an SDK was fetched from, and a directory without it is listed as incomplete</td></tr><tr><td><code>sdk use &lt;name&gt;</code></td><td>makes a fetched SDK the one in use (below)</td></tr><tr><td><code>sdk remove &lt;name&gt;</code></td><td>removes a fetched SDK, and its link if it is in use</td></tr><tr><td><code>--preset &lt;image&gt;</code></td><td>the SDK versions of a GitHub runner image or label (<code>windows-2022</code>, <code>macos-15</code>); by default <code>windows-latest</code> and <code>macos-latest</code></td></tr><tr><td><code>--version</code>, <code>--sdk-version</code>, <code>--msvc-version</code></td><td>a version, whole or in part (<code>15</code>, <code>10.0.26100</code>, <code>14.44</code>), in place of the preset&#39;s; the newest that matches is taken</td></tr><tr><td><code>--sdk-dir &lt;dir&gt;</code></td><td>another directory for SDKs, for a toolchain installed read-only</td></tr><tr><td><code>--links copy</code></td><td>on Windows, copy instead of making junctions and hard links</td></tr></tbody></table><h3 id="the-sdk-in-use" tabindex="-1">The SDK in Use <a class="header-anchor" href="#the-sdk-in-use" aria-label="Permalink to &quot;The SDK in Use&quot;">​</a></h3><p>The SDK fetched last, or the one <code>sdk use</code> names, is the one in use: <code>$XCLANG/sdk/windows</code> and <code>$XCLANG/sdk/macos</code> point to it, a symbolic link, or on Windows a junction, which needs no privilege. That gives the config files a fixed path. A Windows SDK holds a config file per architecture fetched and per driver, <code>&lt;arch&gt;-pc-windows-msvc.cfg</code> and <code>&lt;arch&gt;-pc-windows-msvc-clang-cl.cfg</code>, which name the SDK and its versions; the MSVC targets&#39; own config files read them through <code>sdk/windows</code> (<a href="./../design/windows#msvc-targets">why</a>). On Linux and Windows hosts the macOS targets&#39; config files name <code>sdk/macos</code> as their <code>-isysroot</code> (<a href="./../design/macos#the-sdk-on-linux-and-windows-hosts">why</a>); on macOS hosts they use Xcode&#39;s SDK, and a fetched one takes <code>-isysroot</code>. An SDK fetched with <code>--sdk-dir</code> is outside the toolchain, where its config files do not look.</p><h3 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h3><p><code>cli/sdk-versions.json</code>, built into the program, lists every version the vendors offer:</p><ul><li>38 Windows SDKs from NuGet;</li><li>20 MSVC toolsets from the Visual Studio channels;</li><li>29 macOS SDK packages from Apple&#39;s software update catalogs;</li><li>presets: the versions GitHub&#39;s runner images build with, so a cross build matches what a workflow gets. <code>windows-2022</code> has MSVC 14.44, whose STL still serves Windows 7 SP1 and 8.1.</li></ul><p>With no version given, the preset&#39;s is taken, the macOS 27 SDK too: the releases that carry the command link against it (<a href="./patches">patch 0009</a>).</p><h3 id="what-is-fetched" tabindex="-1">What Is Fetched <a class="header-anchor" href="#what-is-fetched" aria-label="Permalink to &quot;What Is Fetched&quot;">​</a></h3><p><strong>macOS</strong> comes from a Command Line Tools package on <code>swcdn.apple.com</code>, without an Apple ID. Man pages, tools and Perl are left out. On Windows, symlinks become junctions (to directories) and hard links (to files), which need no privilege. The download is 62 MB, 610 MB unpacked.</p><p><strong>Windows</strong> comes from the <code>.vsix</code> packages of Visual Studio and NuGet&#39;s <code>Microsoft.Windows.SDK.CPP</code> packages, laid out as a <code>/winsysroot</code>, as Visual Studio installs it. The <code>.vsix</code> packages hold the CRT and STL: the headers, the STL&#39;s <code>std</code> modules (<code>std.ixx</code>), and per architecture the libraries of the static and DLL runtimes, with the PDBs of the static runtime. A debug link looks for those, and warns without them (LNK4099). On a case-sensitive file system, 3.6k links are added for the spellings Windows code uses. The download is 600 MB for x64 and arm64, 1.8 GB unpacked.</p><h2 id="targets" tabindex="-1">Targets <a class="header-anchor" href="#targets" aria-label="Permalink to &quot;Targets&quot;">​</a></h2><p><code>xclang target add</code> unpacks the archive of a target into the toolchain: its sysroot and runtimes, its compiler-rt, and its config files. The archives of a release are listed in its index, as the channel manifests of rustup list components. No release has an index yet (<a href="./../design/roadmap#target-archives">planned</a>); this one is illustrative:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;23.1.2.7&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;targets&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;x86_64-unknown-linux-musl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Linux x64, musl 1.2.5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;tier&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;sdk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;archive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;xclang-target-23.1.2.7-x86_64-unknown-linux-musl.tar.xz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;sha256&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;…&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;size&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12345678</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;unpacked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">98765432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>The index is <code>xclang-targets-&lt;version&gt;.json</code>, an asset of the release of the toolchain. <code>--index</code> or <code>XCLANG_TARGET_INDEX</code> names another, a URL or a file. The release of the toolchain comes from its CMake package, and an index of another release is refused.</li><li><code>archive</code> is a URL, or a name next to the index. <code>sdk</code> is <code>macos</code>, <code>windows</code> or null; <code>target add</code> says which SDK to fetch.</li><li>An archive is a <code>.tar.xz</code> of regular files below <code>xclang/</code>, as the toolchain archives are, without links. <code>target add</code> refuses to overwrite a file that is not the target&#39;s own, unless given <code>--force</code>. It takes back what it wrote when it fails.</li><li>What a target added is recorded in <code>lib/xclang/targets/&lt;target&gt;.json</code>. <code>target remove</code> deletes those files, and the directories they leave empty.</li><li>The six built-in targets are listed as built in, and cannot be removed.</li></ul><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Every request says <code>User-Agent: xclang/&lt;version&gt;</code>, and nothing else about the user. TLS is rustls, with ring. Certificates are checked against the trust store of the system: Security.framework on macOS, the certificate store on Windows, the CA files of a Linux system. So a CA that a company installs is trusted too. A Linux system without CA files falls back to Mozilla&#39;s roots.</p><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_SDK_DIR</code></td><td>another directory for SDKs, as <code>--sdk-dir</code></td></tr><tr><td><code>XCLANG_JOBS</code></td><td>how many threads unpack; one per CPU by default</td></tr><tr><td><code>XCLANG_TARGET_INDEX</code></td><td>another target index, as <code>--index</code></td></tr><tr><td><code>HTTPS_PROXY</code>, <code>HTTP_PROXY</code>, <code>ALL_PROXY</code>, <code>NO_PROXY</code></td><td>honoured</td></tr><tr><td><code>SSL_CERT_FILE</code></td><td>a CA file, read on Linux</td></tr></tbody></table><p>How the command is built, tested and maintained is in the <a href="./../dev/release-build#the-xclang-command">build pipeline</a>.</p>`,25)])])}const g=s(i,[["render",o]]);export{k as __pageData,g as default};
